<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';
require_once __DIR__.'/_helper.php';
uks_require_access($pdo);

$manage=uks_can_manage($pdo);
$canSensitive=uks_can_view_sensitive($pdo);
$id=max(0,(int)($_GET['id']??$_POST['id']??0));
$kunjunganId=max(0,(int)($_GET['kunjungan_id']??$_POST['kunjungan_id']??0));
$error='';
$flash=uks_flash();

function rujukan_label_jenis(string $v): string { return ['puskesmas'=>'Puskesmas','rumah_sakit'=>'Rumah Sakit','klinik'=>'Klinik','lainnya'=>'Lainnya'][$v]??$v; }
function rujukan_label_cara(string $v): string { return ['diantar_sekolah'=>'Diantar sekolah','diantar_orangtua'=>'Diantar orang tua/wali','datang_sendiri_dengan_persetujuan'=>'Datang sendiri dengan persetujuan','lainnya'=>'Lainnya'][$v]??$v; }
function rujukan_label_status(string $v): string { return ['direncanakan'=>'Direncanakan','dirujuk'=>'Dirujuk','selesai'=>'Selesai','tidak_jadi'=>'Tidak jadi'][$v]??$v; }

if($id>0){
  $st=$pdo->prepare("SELECT r.*,uk.tanggal AS kunjungan_tanggal,uk.waktu AS kunjungan_waktu,s.nis,s.nisn,s.nama,mk.nama AS kelas,g.nama AS pendamping
    FROM uks_rujukan r JOIN uks_kunjungan uk ON uk.id=r.kunjungan_id JOIN siswa s ON s.id=r.siswa_id
    LEFT JOIN guru g ON g.id=r.pendamping_guru_id
    LEFT JOIN siswa_kelas sk ON sk.id=(SELECT sk2.id FROM siswa_kelas sk2 WHERE sk2.siswa_id=s.id AND sk2.tahun_pelajaran_id=(SELECT id FROM tahun_pelajaran WHERE aktif=1 ORDER BY id DESC LIMIT 1) AND sk2.status='aktif' ORDER BY sk2.id DESC LIMIT 1)
    LEFT JOIN master_kelas mk ON mk.id=sk.kelas_id WHERE r.id=? LIMIT 1");
  $st->execute([$id]);$current=$st->fetch();if(!$current)exit('Rujukan tidak ditemukan.');
  if(!uks_teacher_can_view_student($pdo,(int)$current['siswa_id']))deny_access();
  if($manage && !uks_can_manage_student($pdo,(int)$current['siswa_id']))deny_access();
  $kunjunganId=(int)$current['kunjungan_id'];
}

if($kunjunganId>0){
  $kv=$pdo->prepare("SELECT uk.id,uk.siswa_id,uk.tanggal,uk.waktu,s.nis,s.nisn,s.nama,mk.nama AS kelas
    FROM uks_kunjungan uk JOIN siswa s ON s.id=uk.siswa_id
    LEFT JOIN siswa_kelas sk ON sk.id=(SELECT sk2.id FROM siswa_kelas sk2 WHERE sk2.siswa_id=s.id AND sk2.tahun_pelajaran_id=(SELECT id FROM tahun_pelajaran WHERE aktif=1 ORDER BY id DESC LIMIT 1) AND sk2.status='aktif' ORDER BY sk2.id DESC LIMIT 1)
    LEFT JOIN master_kelas mk ON mk.id=sk.kelas_id WHERE uk.id=? LIMIT 1");
  $kv->execute([$kunjunganId]);$visit=$kv->fetch();if(!$visit)exit('Kunjungan tidak ditemukan.');
  if(!uks_teacher_can_view_student($pdo,(int)$visit['siswa_id']))deny_access();
}

if($_SERVER['REQUEST_METHOD']==='POST' && $manage){
  require_valid_csrf();
  $action=(string)($_POST['action']??'save');
  if($action==='delete' && $id>0){
    $pdo->beginTransaction();
    try{$pdo->prepare('DELETE FROM uks_rujukan WHERE id=?')->execute([$id]);uks_audit($pdo,'DELETE',$id,'Menghapus data rujukan UKS');$pdo->commit();uks_flash('Rujukan berhasil dihapus.');redirect('uks/rujukan.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Rujukan tidak dapat dihapus.';}
  } else {
    $kunjunganId=(int)($_POST['kunjungan_id']??0);
    $visitSt=$pdo->prepare('SELECT id,siswa_id,tanggal,waktu FROM uks_kunjungan WHERE id=? LIMIT 1');$visitSt->execute([$kunjunganId]);$visit=$visitSt->fetch();if($visit && !uks_can_manage_student($pdo,(int)$visit['siswa_id'])){deny_access();}
    $jenis=(string)($_POST['tujuan_jenis']??'puskesmas');$fasilitas=trim((string)($_POST['fasilitas_nama']??''));$tanggal=(string)($_POST['tanggal']??date('Y-m-d'));$waktu=(string)($_POST['waktu']??'');$guru=(int)($_POST['pendamping_guru_id']??0);$pendampingNama=trim((string)($_POST['pendamping_nama']??''));$alasan=trim((string)($_POST['alasan']??''));$cara=(string)($_POST['cara_berangkat']??'diantar_orangtua');$status=(string)($_POST['status']??'direncanakan');$hasil=trim((string)($_POST['hasil_tindak_lanjut']??''));$catatan=trim((string)($_POST['catatan']??''));
    if(!$visit)$error='Kunjungan UKS tidak ditemukan.';elseif(!in_array($jenis,['puskesmas','rumah_sakit','klinik','lainnya'],true)||$fasilitas===''||$tanggal===''||$alasan==='')$error='Tujuan fasilitas, tanggal, dan alasan rujukan wajib diisi.';elseif(!in_array($cara,['diantar_sekolah','diantar_orangtua','datang_sendiri_dengan_persetujuan','lainnya'],true)||!in_array($status,['direncanakan','dirujuk','selesai','tidak_jadi'],true))$error='Pilihan rujukan tidak valid.';else{
      try{$pdo->beginTransaction();
        $existing=$pdo->prepare('SELECT id FROM uks_rujukan WHERE kunjungan_id=? AND id<>? LIMIT 1');$existing->execute([$kunjunganId,$id]);$exists=(int)($existing->fetchColumn()?:0);
        if($exists>0)throw new RuntimeException('Kunjungan ini sudah memiliki rujukan.');
        $gid=$guru>0?$guru:null;
        if($id>0){$st=$pdo->prepare('UPDATE uks_rujukan SET tujuan_jenis=?,fasilitas_nama=?,tanggal=?,waktu=?,pendamping_guru_id=?,pendamping_nama=?,alasan=?,cara_berangkat=?,status=?,hasil_tindak_lanjut=?,catatan=? WHERE id=?');$st->execute([$jenis,$fasilitas,$tanggal,$waktu!==''?$waktu:null,$gid,$pendampingNama!==''?$pendampingNama:null,$alasan,$cara,$status,$hasil!==''?$hasil:null,$catatan!==''?$catatan:null,$id]);uks_audit($pdo,'UPDATE',$id,'Memperbarui rujukan UKS');$rid=$id;}else{$st=$pdo->prepare('INSERT INTO uks_rujukan(kunjungan_id,siswa_id,tujuan_jenis,fasilitas_nama,tanggal,waktu,pendamping_guru_id,pendamping_nama,alasan,cara_berangkat,status,hasil_tindak_lanjut,catatan,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$st->execute([$kunjunganId,(int)$visit['siswa_id'],$jenis,$fasilitas,$tanggal,$waktu!==''?$waktu:null,$gid,$pendampingNama!==''?$pendampingNama:null,$alasan,$cara,$status,$hasil!==''?$hasil:null,$catatan!==''?$catatan:null,user_id()]);$rid=(int)$pdo->lastInsertId();uks_audit($pdo,'CREATE',$rid,'Membuat rujukan UKS');}
        $summary=rujukan_label_jenis($jenis).' — '.$fasilitas.' — '.rujukan_label_status($status);
        $pdo->prepare('UPDATE uks_kunjungan SET rujukan=? WHERE id=?')->execute([$summary,$kunjunganId]);
        $pdo->commit();uks_flash('Data rujukan berhasil disimpan.');redirect('uks/rujukan.php?id='.$rid);
      }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Gagal menyimpan rujukan.';}
    }
  }
}

if($id===0 && $kunjunganId===0){
  $from=(string)($_GET['from']??date('Y-m-01'));$to=(string)($_GET['to']??date('Y-m-d'));$statusFilter=(string)($_GET['status']??'');$jenisFilter=(string)($_GET['jenis']??'');$q=trim((string)($_GET['q']??''));$where=['r.tanggal BETWEEN ? AND ?'];$params=[$from,$to];
  if($statusFilter!==''){$where[]='r.status=?';$params[]=$statusFilter;}if($jenisFilter!==''){$where[]='r.tujuan_jenis=?';$params[]=$jenisFilter;}if($q!==''){$where[]='(s.nama LIKE ? OR s.nis LIKE ? OR s.nisn LIKE ? OR r.fasilitas_nama LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like,$like);}
  $scope=uks_teacher_scope($pdo,'s');$where[]=$scope['sql'];$params=array_merge($params,$scope['params']);
  $st=$pdo->prepare("SELECT r.*,s.nama,s.nis,mk.nama AS kelas FROM uks_rujukan r JOIN siswa s ON s.id=r.siswa_id LEFT JOIN siswa_kelas sk ON sk.id=(SELECT sk2.id FROM siswa_kelas sk2 WHERE sk2.siswa_id=s.id AND sk2.tahun_pelajaran_id=(SELECT id FROM tahun_pelajaran WHERE aktif=1 ORDER BY id DESC LIMIT 1) AND sk2.status='aktif' ORDER BY sk2.id DESC LIMIT 1) LEFT JOIN master_kelas mk ON mk.id=sk.kelas_id WHERE ".implode(' AND ',$where).' ORDER BY r.tanggal DESC,r.id DESC LIMIT 200');$st->execute($params);$rows=$st->fetchAll();
  $page_title='Rujukan UKS';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';?>
  <main class="main uks-module-page"><header class="topbar"><div class="topbar-title">Rujukan UKS</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content"><div class="page-header"><div><h1><i class="bi bi-hospital-fill"></i> Rujukan UKS</h1><p>Rekap rujukan siswa ke Puskesmas, Rumah Sakit, dan fasilitas kesehatan lainnya.</p></div><a class="btn btn-secondary" href="<?=BASE_URL?>uks/index.php"><i class="bi bi-arrow-left"></i> Kembali</a></div>
  <?php if($flash):?><div class="alert alert-success"><?=e($flash)?></div><?php endif;?><div class="form-card"><form method="get" class="form-grid"><div class="form-group"><label>Pencarian</label><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Nama/NIS/fasilitas..."></div><div class="form-group"><label>Dari</label><input class="form-control" type="date" name="from" value="<?=e($from)?>"></div><div class="form-group"><label>Sampai</label><input class="form-control" type="date" name="to" value="<?=e($to)?>"></div><div class="form-group"><label>Tujuan</label><select class="form-control" name="jenis"><option value="">Semua</option><?php foreach(['puskesmas'=>'Puskesmas','rumah_sakit'=>'Rumah Sakit','klinik'=>'Klinik','lainnya'=>'Lainnya'] as $k=>$v):?><option value="<?=$k?>" <?=$jenisFilter===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="form-group"><label>Status</label><select class="form-control" name="status"><option value="">Semua</option><?php foreach(['direncanakan'=>'Direncanakan','dirujuk'=>'Dirujuk','selesai'=>'Selesai','tidak_jadi'=>'Tidak jadi'] as $k=>$v):?><option value="<?=$k?>" <?=$statusFilter===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="form-actions"><button class="btn btn-primary"><i class="bi bi-search"></i> Cari</button></div></form></div>
  <div class="form-card"><div class="table-responsive"><table class="data-table"><thead><tr><th>Siswa</th><th>Kelas</th><th>Tujuan</th><th>Fasilitas</th><th>Tanggal</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" class="empty-state">Belum ada rujukan.</td></tr><?php else:foreach($rows as $r):?><tr><td><strong><?=e($r['nama'])?></strong><div class="meta"><?=e($r['nis'])?></div></td><td><?=e($r['kelas']??'-')?></td><td><?=e(rujukan_label_jenis($r['tujuan_jenis']))?></td><td><?=e($r['fasilitas_nama'])?></td><td><?=e($r['tanggal'])?></td><td><span class="badge <?=e($r['status'])?>"><?=e(rujukan_label_status($r['status']))?></span></td><td><a class="btn btn-sm btn-secondary" href="<?=BASE_URL?>uks/rujukan.php?id=<?=$r['id']?>" title="Detail"><i class="bi bi-eye"></i></a><?php if($manage):?><a class="btn btn-sm btn-primary" href="<?=BASE_URL?>uks/rujukan.php?id=<?=$r['id']?>&edit=1" title="Edit"><i class="bi bi-pencil-square"></i></a><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></div></section></main><?php require_once __DIR__.'/../layouts/footer.php';exit;
}

if(!$current){$current=['id'=>0,'kunjungan_id'=>$kunjunganId,'siswa_id'=>$visit['siswa_id']??0,'tujuan_jenis'=>'puskesmas','fasilitas_nama'=>'','tanggal'=>$visit['tanggal']??date('Y-m-d'),'waktu'=>$visit['waktu']??'','pendamping_guru_id'=>null,'pendamping_nama'=>'','alasan'=>'','cara_berangkat'=>'diantar_orangtua','status'=>'direncanakan','hasil_tindak_lanjut'=>'','catatan'=>''];}
$editMode=$id>0 && isset($_GET['edit']);
if($id>0 && !$editMode){$page_title='Detail Rujukan UKS';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';?>
<main class="main"><header class="topbar"><div class="topbar-title">Detail Rujukan UKS</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content"><div class="page-header"><div><h1><i class="bi bi-hospital-fill"></i> Detail Rujukan</h1><p><?=e($current['nama'])?> · <?=e($current['kelas']??'-')?> · <?=e($current['tanggal'])?></p></div><div class="page-header-actions"><a class="btn btn-secondary" href="<?=BASE_URL?>uks/rujukan.php"><i class="bi bi-arrow-left"></i> Kembali</a><a class="btn btn-secondary" target="_blank" href="<?=BASE_URL?>uks/rujukan_cetak.php?id=<?=$id?>"><i class="bi bi-printer"></i> Cetak Surat</a><?php if($manage):?><a class="btn btn-primary" href="<?=BASE_URL?>uks/rujukan.php?id=<?=$id?>&edit=1"><i class="bi bi-pencil-square"></i> Edit</a><?php endif;?></div></div><div class="form-card"><div class="detail-grid"><div><small>Siswa</small><strong><?=e($current['nama'])?></strong></div><div><small>Kelas</small><strong><?=e($current['kelas']??'-')?></strong></div><div><small>Tujuan</small><strong><?=e(rujukan_label_jenis($current['tujuan_jenis']))?></strong></div><div><small>Fasilitas</small><strong><?=e($current['fasilitas_nama'])?></strong></div><div><small>Tanggal</small><strong><?=e($current['tanggal'])?> <?=e($current['waktu']??'')?></strong></div><div><small>Status</small><strong><?=e(rujukan_label_status($current['status']))?></strong></div><div><small>Pendamping</small><strong><?=e($current['pendamping']??$current['pendamping_nama']??'-')?></strong></div><div><small>Cara</small><strong><?=e(rujukan_label_cara($current['cara_berangkat']))?></strong></div><div class="full"><small>Alasan Rujukan</small><div><?=nl2br(e($current['alasan']))?></div></div><div class="full"><small>Hasil/Tindak Lanjut</small><div><?=nl2br(e($current['hasil_tindak_lanjut']??'-'))?></div></div><div class="full"><small>Catatan</small><div><?=nl2br(e($current['catatan']??'-'))?></div></div></div></div></section></main><?php require_once __DIR__.'/../layouts/footer.php';exit;}

$teachers=$pdo->query("SELECT id,nama,nip FROM guru WHERE status='aktif' ORDER BY nama")->fetchAll();
