<main class="main"><header class="topbar"><div class="topbar-title">Rujukan UKS</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content"><div class="page-header"><div><h1><i class="bi bi-hospital-fill"></i> <?=$id>0?'Edit':'Tambah'?> Rujukan</h1><p><?=e($visit['nama']??$current['nama']??'-')?> · <?=e($visit['kelas']??$current['kelas']??'-')?></p></div><a class="btn btn-secondary" href="<?=BASE_URL?>uks/kunjungan_detail.php?id=<?=((int)($current['kunjungan_id']??$kunjunganId))?>"><i class="bi bi-arrow-left"></i> Kembali ke Kunjungan</a></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="kunjungan_id" value="<?=((int)($current['kunjungan_id']??$kunjunganId))?>"><div class="form-card"><div class="form-grid"><div class="form-group"><label>Tujuan Fasilitas *</label><select class="form-control" name="tujuan_jenis" required><?php foreach(['puskesmas'=>'Puskesmas','rumah_sakit'=>'Rumah Sakit','klinik'=>'Klinik','lainnya'=>'Lainnya'] as $k=>$v):?><option value="<?=$k?>" <?=$current['tujuan_jenis']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="form-group"><label>Nama Fasilitas *</label><input class="form-control" name="fasilitas_nama" value="<?=e($current['fasilitas_nama'])?>" placeholder="Contoh: Puskesmas Plaosan" required></div><div class="form-group"><label>Tanggal *</label><input class="form-control" type="date" name="tanggal" value="<?=e($current['tanggal'])?>" required></div><div class="form-group"><label>Waktu</label><input class="form-control" type="time" name="waktu" value="<?=e($current['waktu']??'')?>"></div><div class="form-group"><label>Pendamping Guru</label><select class="form-control" name="pendamping_guru_id"><option value="0">-- Tidak ditentukan --</option><?php foreach($teachers as $t):?><option value="<?=$t['id']?>" <?=((int)($current['pendamping_guru_id']??0)===(int)$t['id'])?'selected':''?>><?=e($t['nama'])?><?=!empty($t['nip'])?' · '.e($t['nip']):''?></option><?php endforeach;?></select></div><div class="form-group"><label>Pendamping Lainnya</label><input class="form-control" name="pendamping_nama" value="<?=e($current['pendamping_nama']??'')?>" placeholder="Jika bukan guru"></div><div class="form-group form-group-full"><label>Alasan Rujukan *</label><textarea class="form-control" name="alasan" rows="3" required><?=e($current['alasan'])?></textarea></div><div class="form-group"><label>Cara Berangkat</label><select class="form-control" name="cara_berangkat"><?php foreach(['diantar_sekolah'=>'Diantar sekolah','diantar_orangtua'=>'Diantar orang tua/wali','datang_sendiri_dengan_persetujuan'=>'Datang sendiri dengan persetujuan','lainnya'=>'Lainnya'] as $k=>$v):?><option value="<?=$k?>" <?=$current['cara_berangkat']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="form-group"><label>Status</label><select class="form-control" name="status"><?php foreach(['direncanakan'=>'Direncanakan','dirujuk'=>'Dirujuk','selesai'=>'Selesai','tidak_jadi'=>'Tidak jadi'] as $k=>$v):?><option value="<?=$k?>" <?=$current['status']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="form-group form-group-full"><label>Hasil / Tindak Lanjut</label><textarea class="form-control" name="hasil_tindak_lanjut" rows="3"><?=e($current['hasil_tindak_lanjut']??'')?></textarea></div><div class="form-group form-group-full"><label>Catatan</label><textarea class="form-control" name="catatan" rows="2"><?=e($current['catatan']??'')?></textarea></div></div></div><div class="form-actions"><button class="btn btn-primary"><i class="bi bi-save"></i> Simpan Rujukan</button><a class="btn btn-secondary" href="<?=BASE_URL?>uks/kunjungan_detail.php?id=<?=((int)($current['kunjungan_id']??$kunjunganId))?>">Batal</a></div></form></section></main><?php require_once __DIR__.'/../layouts/footer.php';
